    // switch inside `u()` carries the whole branch — the boxes, the paddings,
    // the pill, the disc and the offset block all flow through it.
    const desk = !s.narrow
    const tab = isTablet(s)
    const z = desk ? 0.82 : 1
    const u = (v) => `${Math.round(v * z * 10) / 10}px`

